'use strict';
(() => {
const data=window.BENCHMARK, $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const category=id=>data.categories.find(c=>c.id===id), task=id=>data.tasks.find(t=>t.id===id);
const state={category:'all',arm:'all',search:'',limit:8};let activeDemo='dishwasher',lastFocused=null;
const icons=['↳','◉','⑂','◒','⇢'];
$('#reasoning-grid').innerHTML=data.categories.map((c,i)=>`<button class="reasoning-card" data-category-link="${c.id}" aria-label="Explore ${esc(c.name)} tasks"><span class="reasoning-number">0${i+1}<span>${icons[i]}</span></span><h3>${esc(c.name)}</h3><p>${esc(c.description)}</p><small>8 tasks · Explore family ↗</small></button>`).join('');
$('#category-filters').innerHTML=[{id:'all',name:'All tasks'},...data.categories].map(c=>`<button data-category="${c.id}" class="${c.id==='all'?'active':''}" aria-pressed="${c.id==='all'}">${esc(c.name)}</button>`).join('');
function render(){
 const results=data.tasks.filter(t=>(state.category==='all'||t.category===state.category)&&(state.arm==='all'||t.arm===state.arm)&&(!state.search||[t.name,t.id,t.instruction,category(t.category).name,t.arm+' arm'].join(' ').toLowerCase().includes(state.search)));
 const shown=results.slice(0,state.limit);
 $('#result-count').textContent=`Showing ${shown.length} of ${results.length} ${results.length===1?'task':'tasks'}`;
 $('#task-grid').innerHTML=shown.map(t=>`<button class="task-card" data-task="${t.id}" aria-label="Explore ${esc(t.name)}, ${t.arm}-arm task"><span class="task-photo"><img src="${t.image}" alt="Simulation scene for ${esc(t.name)}" loading="lazy" width="480" height="360"><span class="task-arm">${t.arm==='single'?'Single arm':'Dual arm'}</span>${t.video?'<span class="task-play" aria-hidden="true">▶</span>':''}</span><span class="task-body"><span class="task-family">${esc(category(t.category).name)}</span><h3>${esc(t.name)}</h3><p>${esc(t.instruction)}</p><span class="task-card-bottom"><span>${t.arm==='single'?'50 converted episodes':`${t.publishedEpisodes} published ${t.publishedEpisodes===1?'sample':'episodes'}`}</span><b aria-hidden="true">↗</b></span></span></button>`).join('');
 $('#empty-state').hidden=results.length>0;$('#load-more').hidden=shown.length>=results.length;
 $('#load-more').textContent=`Show more tasks (${results.length-shown.length} remaining) ↓`;
 $$('[data-category]').forEach(b=>{const active=b.dataset.category===state.category;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))});
 $$('[data-arm]').forEach(b=>{const active=b.dataset.arm===state.arm;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))});
}
function reset(){Object.assign(state,{category:'all',arm:'all',search:'',limit:8});$('#task-search').value='';render()}
$('#task-search').addEventListener('input',e=>{state.search=e.target.value.trim().toLowerCase();state.limit=8;render()});
$('#reset-filters').addEventListener('click',reset);$('#empty-reset').addEventListener('click',reset);
$('#load-more').addEventListener('click',()=>{const before=state.limit;state.limit+=8;render();const firstNew=$$('.task-card')[before];if(firstNew)firstNew.focus({preventScroll:true})});
function openTask(id){const t=task(id);if(!t)return;lastFocused=document.activeElement;$('#hero-video').pause();$('#demo-video').pause();
 const availability=t.github?`Published on private GitHub: ${t.publishedEpisodes} ${t.publishedEpisodes===1?'episode':'episodes'}. ${t.arm==='dual'?(t.publishedEpisodes===1?'This is a one-episode sample release.':'The complete 50-episode Category 1 export is available.'):'The complete 50-episode Category 1 export is available.'}`:'The 50-episode LeRobot export is validated locally; this task is not part of the current GitHub release.';
 const media=t.video?`<video controls muted playsinline preload="metadata" poster="${t.image}" aria-label="${esc(t.name)} demonstration at normal speed"><source src="${t.video}" type="video/mp4"></video>`:`<img src="${t.image}" alt="Recorded overview camera frame for ${esc(t.name)}">`;
 $('#dialog-content').innerHTML=`<div class="dialog-media">${media}</div><div class="preview-view-controls">${t.multiViewVideo?`<button type="button" data-preview-view="main" aria-pressed="true">Main view</button><button type="button" data-preview-view="all" aria-pressed="false">All three cameras</button>`:''}</div><div class="preview-label">${t.video?'Complete first episode · normal speed · main camera':'Recorded first-frame preview · overview camera'}</div><div class="dialog-body"><p class="eyebrow">${esc(category(t.category).name)} / ${t.arm==='single'?'SINGLE ARM':'DUAL ARM'}</p><h2 id="dialog-title">${esc(t.name)}</h2><p class="dialog-instruction">${esc(t.instruction)}</p><dl class="dialog-facts"><div><dt>${t.arm==='single'?'Converted episodes':'Published episodes'}</dt><dd>${t.episodes}</dd></div><div><dt>Camera streams</dt><dd>${t.cameras} RGB views</dd></div><div><dt>Control frequency</dt><dd>${t.fps} Hz</dd></div><div><dt>Action dimension</dt><dd>${t.actionDimension}D</dd></div></dl>${t.driveReviewVideos?`<section class="archive-previews"><h3>Dual-arm review recordings</h3><p>The Drive manifest lists ${t.driveRecordEpisodes} trajectories. These five selected combined-camera videos are for review; full training image streams are not included in this Drive preview selection.</p><div class="archive-video-links">${t.driveReviewVideos.map(v=>`<a href="${v.viewUrl}" target="_blank" rel="noopener">Episode ${Number(v.name.match(/\d+/)[0])} <span aria-hidden="true">↗</span></a>`).join('')}</div></section>`:''}<p class="availability">${availability}</p><div class="dialog-links">${t.drive?`<a class="button primary" target="_blank" rel="noopener" href="${t.drive}">Task records on Drive ↗</a>`:''}${t.github?`<a class="button secondary" target="_blank" rel="noopener" href="${t.github}">LeRobot on GitHub ↗</a>`:''}<a class="text-link" href="#data" id="dialog-release-link">Release details →</a></div><p class="dialog-note">${t.drive?'Drive keeps task recordings and development history; it is separate from the LeRobot training dataset.':'This task was not listed in the inspected Drive archive. That archive is separate from its validated local LeRobot export.'} ${t.github?'Private repository access is required.':''}</p><p class="dialog-note"><b>Controller:</b> ${esc(t.actionSemantics)}. ${t.frames.toLocaleString()} timesteps in this ${t.arm==='single'?'canonical export':'published export'}. ${t.trainingCheck?'Official loader and one-step ACT compatibility checks passed.':'See the task validation report for the sample’s technical checks.'}</p></div>`;
 $('#task-dialog').showModal();document.body.style.overflow='hidden';
 $$('#dialog-content [data-preview-view]').forEach(button=>button.addEventListener('click',()=>{
  const video=$('#dialog-content video'), time=video.currentTime, playing=!video.paused, all=button.dataset.previewView==='all';
  if(button.getAttribute('aria-pressed')==='true')return;
  video.pause();video.src=all?t.multiViewVideo:t.video;video.removeAttribute('poster');
  video.addEventListener('loadedmetadata',()=>{video.currentTime=Math.min(time,video.duration||time);if(playing)video.play().catch(()=>{})},{once:true});video.load();
  $$('#dialog-content [data-preview-view]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));
  $('#dialog-content .preview-label').textContent=all?'Complete first episode · normal speed · three cameras':'Complete first episode · normal speed · main camera';
 }));
$('#dialog-release-link').addEventListener('click',()=>$('#task-dialog').close());
}
const dialog=$('#task-dialog');$('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});dialog.addEventListener('close',()=>{dialog.querySelector('video')?.pause();document.body.style.overflow='';if(lastFocused?.isConnected)lastFocused.focus({preventScroll:true})});
document.addEventListener('click',e=>{const card=e.target.closest('[data-task]');if(card)openTask(card.dataset.task);const cat=e.target.closest('[data-category]');if(cat){state.category=cat.dataset.category;state.limit=8;render()}const family=e.target.closest('[data-category-link]');if(family){state.category=family.dataset.categoryLink;state.arm='all';state.search='';state.limit=8;$('#task-search').value='';render();$('#tasks').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'})}const arm=e.target.closest('[data-arm]');if(arm){state.arm=arm.dataset.arm;state.limit=8;render()}});
const hero=$('#hero-video');$('#hero-play').addEventListener('click',()=>{if(hero.paused)hero.play().catch(()=>toast('Use the demonstration player below to watch this preview.'));else hero.pause()});function syncHero(){const playing=!hero.paused;$('#hero-play').textContent=playing?'Ⅱ':'▶';$('#hero-play').setAttribute('aria-label',playing?'Pause dishwasher preview':'Play dishwasher preview')};hero.addEventListener('play',syncHero);hero.addEventListener('pause',syncHero);
const demoIds=['dishwasher','purse_memory','water_recovery','boba_tea_allocation','shelf_assembly'];
$('#demo-choices').innerHTML=demoIds.map((id,i)=>{const t=task(id);return `<button class="demo-choice ${id===activeDemo?'active':''}" data-demo="${id}" aria-pressed="${id===activeDemo}"><img src="${t.image}" width="100" height="76" loading="lazy" alt=""><span><small>0${i+1} / ${esc(category(t.category).name)}</small><b>${esc(t.name)}</b></span><span class="arrow" aria-hidden="true">↗</span></button>`}).join('');
$('#dual-demo-grid').innerHTML=['task5_toolbox_sorting','task13_container_transfer','task21_table_cleaning','task28_plant_repotting','task37_tea_storage'].map(id=>{const t=task(id);return `<button class="dual-record-card" data-task="${t.id}"><img src="${t.image}" loading="lazy" alt="${esc(t.name)} dual-arm scene"><span><small>${esc(category(t.category).name)}</small><b>${esc(t.name)}</b><em>5 Drive review videos ↗</em></span></button>`}).join('');
$('#demo-instruction').textContent=task(activeDemo).instruction;
$$('[data-demo]').forEach(b=>b.addEventListener('click',()=>{activeDemo=b.dataset.demo;const t=task(activeDemo),v=$('#demo-video');v.pause();v.poster=t.image;v.src=t.video;v.load();$('#demo-title').textContent=t.name;$('#demo-category').textContent=category(t.category).name.toUpperCase();$('#demo-instruction').textContent=t.instruction;$$('[data-demo]').forEach(x=>{const on=x===b;x.classList.toggle('active',on);x.setAttribute('aria-pressed',String(on))})}));$('#demo-details').addEventListener('click',()=>openTask(activeDemo));
const code={load:`from pathlib import Path\nfrom lerobot.datasets.lerobot_dataset import LeRobotDataset\n\ndataset = LeRobotDataset(\n    repo_id="local/dishwasher_three_view",\n    root=Path("data/01_conditional/single_arm/dishwasher"),\n    video_backend="pyav",\n)\n\nsample = dataset[0]\nprint(sample["action"].shape)  # torch.Size([7])\nprint(sample["observation.state"].shape)  # [9]`,download:`# Requires authorized access to the private repository.\n# Install Git LFS before cloning.\ngit lfs install\ngit clone https://github.com/yutaod-crypto/robodataSim-data.git\ncd robodataSim-data\ngit lfs pull\n\n# Verify downloaded payloads.\nsha256sum -c SHA256SUMS\n\n# In a Python 3.12 virtual environment:\npip install "lerobot==0.4.4"`,layout:`data/<category>/<embodiment>/<task>/\n├── data/                 # Actions and state in Parquet\n├── meta/\n│   ├── info.json         # Feature and controller schema\n│   ├── stats.json        # Dataset statistics\n│   ├── tasks.parquet     # Task instructions\n│   └── episodes/         # Episode-to-file references\n├── videos/               # MP4s, grouped by camera\n├── provenance/           # Source and conversion evidence\n├── validation.json       # Technical validation\n└── README.md             # Task-specific contract`};let currentCode='load';$('#code-text').textContent=code.load;
function selectCode(b){currentCode=b.dataset.code;$('#code-text').textContent=code[currentCode];$('#code-content').setAttribute('aria-labelledby',b.id);$$('[data-code]').forEach(x=>{const on=x===b;x.classList.toggle('active',on);x.setAttribute('aria-selected',String(on));x.tabIndex=on?0:-1})}
$$('[data-code]').forEach((b,i)=>{b.addEventListener('click',()=>selectCode(b));b.addEventListener('keydown',e=>{const tabs=$$('[data-code]');let index;if(e.key==='ArrowRight')index=(i+1)%tabs.length;if(e.key==='ArrowLeft')index=(i+tabs.length-1)%tabs.length;if(e.key==='Home')index=0;if(e.key==='End')index=tabs.length-1;if(index!==undefined){e.preventDefault();selectCode(tabs[index]);tabs[index].focus()}})});
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3200)}
$('#copy-code').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(code[currentCode]);toast('Code copied');$('#copy-code').textContent='Copied';setTimeout(()=>$('#copy-code').textContent='Copy',2000)}catch{const selection=getSelection(),range=document.createRange();range.selectNodeContents($('#code-text'));selection.removeAllRanges();selection.addRange(range);toast('Code selected. Press Ctrl+C or ⌘C to copy.')}});
$('.menu-button').addEventListener('click',()=>{const open=$('#nav').classList.toggle('open');$('.menu-button').setAttribute('aria-expanded',String(open))});$$('#nav a').forEach(a=>a.addEventListener('click',()=>{$('#nav').classList.remove('open');$('.menu-button').setAttribute('aria-expanded','false')}));
render();
})();
